def read(p):return json.loads(Path(p).read_text())
def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def fmt(v,n=4):return 'N/A'if v is None else str(v)if isinstance(v,str)else f'{v:.{n}f}'
def pct(v):return 'N/A'if v is None else f'{100*v:.2f}%'
def name(proc):
 for tag,title in [('original','Original recorded selection rolling-v2'),('SAVED_ADJUSTED_POINT_DIRECTION_RETAINED_PRECISION','Saved adjusted point rolling-v2'),('SAVED_RAW_PROJECTION_DIRECTION_RETAINED_PRECISION','Saved raw projection rolling-v2'),('alwaysOver','Always Over rolling-v2'),('alwaysUnder','Always Under rolling-v2')]:
  if proc=='v2-server-retained-per-game-T90-archive-selection-v2:'+tag:return title
 for k,v in sorted(NAMES.items(),key=lambda x:-len(x[0])):
  if proc.startswith(k):return v+(' [strict-current inputs]'if'strict-current'in proc else'')+(' / known-target-time reconstruction'if'known-target-time'in proc else'')
 return proc

def compact_name(r):return name(r['procedure_id'])+' / '+str(r.get('history_regime')or'fixed recorded')+' / '+str(r.get('product_id',''))+(' / '+str(r.get('decision_rule',''))if r.get('decision_rule')else'')
def source_rows(bindings,role):
 rows=[]
 for b in bindings:
  if b['role']!=role:continue
  p=ROOT/b['path'];assert sha(p)==b['sha256']
  excluded={tuple(v)for v in b.get('exclude_partial_leaf_signatures',[])}
  meta=p.with_name('CURRENT_REPORTING_ANNOTATIONS_V2.json');annotations={}
  if meta.exists():
   obj=read(meta);assert obj['source_score_sha256']==b['sha256'];annotations={v['record_id']:v for v in obj['rows']}

  for row in read(p):
   if (row.get('record_kind')=='prop_threshold_probability_evaluation'or(row.get('record_kind')=='prop_selection_evaluation'and row.get('decision_rule')=='P2'))and tuple(row.get(k)for k in('target','procedure_id','history_regime'))in excluded:continue
   if str(row.get('method_id',row.get('strategy',''))).startswith('CONTROL-'):continue
   row=dict(row);addition=annotations.get(row['record_id'],{})
   if row.get('record_kind')=='prop_selection_evaluation':
    stats=dict(row['selection_metrics']);counts=addition.get('law_origin_counts')
    if counts is not None:stats['fallback_issued']=counts['actual_source_fallback_count']
    den=addition.get('denominators')
    if den is not None:
     for k in('admitted_forecast_opportunities','unavailable_forecast_opportunities','admitted_rule_abstentions'):stats[k]=den[k]
    row['_fallback_scope']='SELECTED_SIDE_SUBSET'if counts is not None else'ADMITTED_FORECAST_POOL'if'fallback_issued'in stats else'UNRETAINED'
    row['selection_metrics']=stats
   rows.append(dict(row,_source=b['path'],_panel=b.get('panel')))

 return rows

def ismain(r):return r.get('cohort_id','ALL')=='ALL'and r.get('K')is None and r.get('rank_scope')is None

def roll_selection(rows):
 groups={}
 for r in rows:
  if r.get('record_kind')!='prop_selection_evaluation'or not ismain(r):continue
  # Different observed clocks and exact source versions remain in their source rows;
  # this aggregate covers one registered rolling product, no fixed-Friday mixing.
  key=tuple(r.get(k)for k in('target','procedure_id','history_regime','product_id','decision_rule','side'))
  g=groups.setdefault(key,dict(target=r['target'],procedure_id=r['procedure_id'],history_regime=r.get('history_regime'),product_id=r.get('product_id'),decision_rule=r.get('decision_rule',r.get('strategy')),side=r['side'],n=0,selected=0,wins=0,losses=0,status=collections.Counter(),eligible=0,admitted=0,admitted_known=True,unavailable=0,unavailable_known=True,fallback=0,fallback_known=True,fallback_scope=r.get('_fallback_scope','UNRETAINED'),fallback_denominator=0,weeks=set(),games=0,source_records=[]))
  m=r['selection_metrics'];g['n']+=r['n'];g['selected']+=r['forecast_rows'];g['wins']+=m['WIN'];g['losses']+=m['LOSS'];g['status'].update(m['status_counts']);g['eligible']+=m.get('full_offer_universe',m.get('selection_pool_count',0));g['admitted']+=m.get('admitted_forecast_opportunities',0);g['admitted_known']=g['admitted_known'] and 'admitted_forecast_opportunities'in m;g['unavailable']+=m.get('unavailable_forecast_opportunities',0);g['unavailable_known']=g['unavailable_known']and'unavailable_forecast_opportunities'in m;g['fallback']+=m.get('fallback_issued',0);g['fallback_known']=g['fallback_known']and'fallback_issued'in m;g['fallback_denominator']+=r['forecast_rows']if r.get('_fallback_scope')=='SELECTED_SIDE_SUBSET'else m.get('admitted_forecast_opportunities',0);g['weeks'].update(r.get('evaluation_weeks',[r['week']]));g['games']+=r.get('unique_games',0);g['source_records'].append(dict(path=r['_source'],record_id=r['record_id']))
 for g in groups.values():
  g['admitted']=g['admitted']if g.pop('admitted_known')else None;g['unavailable']=g['unavailable']if g.pop('unavailable_known')else None;g['fallback']=g['fallback']if g.pop('fallback_known')else None;g['fallback_denominator']=g['fallback_denominator']if g['fallback']is not None else None;g['fallback_rate']=g['fallback']/g['fallback_denominator']if g['fallback_denominator']else None;g['weeks']=sorted(g['weeks']);g['status']=dict(g['status']);g['hit_rate']=g['wins']/g['n']if g['n']else None;g['coverage']=g['selected']/g['eligible']if g['eligible']else None
 return list(groups.values())

def roll_probability(rows):
 groups={}
 for r in rows:
  if r.get('record_kind')!='prop_threshold_probability_evaluation':continue
  key=tuple(r.get(k)for k in('target','procedure_id','history_regime','product_id'))
  g=groups.setdefault(key,dict(target=r['target'],procedure_id=r['procedure_id'],history_regime=r.get('history_regime'),product_id=r.get('product_id'),n=0,loss_sum=0.,eligible=0,weeks=set(),source_records=[]))
  if r.get('brier')is not None:g['n']+=r['n'];g['loss_sum']+=r['n']*r['brier']
  g['eligible']+=r.get('forecast_rows',0);g['weeks'].update(r.get('evaluation_weeks',[r['week']]));g['source_records'].append(dict(path=r['_source'],record_id=r['record_id']))
 for g in groups.values():g['weeks']=sorted(g['weeks']);g['brier']=g.pop('loss_sum')/g['n']if g['n']else None;g['coverage']=g['n']/g['eligible']if g['eligible']else None
 return list(groups.values())

def maxima(rows,metric='hit_rate',minimize=False):
 rr=[r for r in rows if r.get(metric)is not None and r['n']>0]
 if not rr:return []
 # Full two-week leaders only; one-week maxima remain explicitly separate outputs.
 full=[r for r in rr if r['weeks']==[6,7]];rr=full or rr;best=(min if minimize else max)(r[metric]for r in rr)
 return sorted([r for r in rr if math.isclose(r[metric],best,rel_tol=0,abs_tol=1e-12)],key=lambda r:(-r['n'],r['procedure_id'],str(r.get('product_id'))))

def hitcell(rows):
 if not rows:return 'Unavailable'
 r=rows[0];subset=' [fallback-law subset only]'if r.get('product_id')=='saved_parametric_law'and(':D1'in r['procedure_id']or':D2'in r['procedure_id'])else'';return f"{compact_name(r)}{subset}: **{r['wins']}/{r['n']} ({pct(r['hit_rate'])})**, selected {r['selected']}, coverage {pct(r['coverage'])}"+(f"; {len(rows)} tied recipes"if len(rows)>1 else'')

def precision(r):
 if r['target']=='anytime_td':return 'N/A: probability product'
 p=r.get('precision_counts')or{};yards=r['target']in('pass_yd','rush_yd','rec_yd','rush_rec_yd');keys=('abs_lt_10','abs_le_10')if yards else('abs_lt_5','abs_le_5')if r['target']=='nick-chart-ppr-v1'else('abs_lt_1','abs_le_1')
 return '; '.join(k+':'+str(p[k]['numerator'])+'/'+str(p[k]['denominator'])for k in keys if k in p)or'N/A; source does not retain count'

def write_table(path,rows):
 path.write_text(json.dumps(rows,indent=2,allow_nan=False)+'\n')
 if rows:
  columns=list(dict.fromkeys(k for r in rows for k in r));
  with path.with_suffix('.csv').open('w',newline='')as f:
   writer=csv.DictWriter(f,fieldnames=columns);writer.writeheader();writer.writerows({k:json.dumps(v,separators=(',',':'))if isinstance(v,(list,dict))else v for k,v in r.items()}for r in rows)

